import { fetch } from 'undici';

export async function getModelSpec(modelName: string, token: string): Promise<any> {
    const url = 'https://api.clip.jina.ai/api/v1/models/?model_name=' + modelName;

    const response = await fetch(url, {
        headers: {
            Authorization: `${token}`,
        },
    });

    if (response.status === 401) {
        throw new Error('The given Jina auth token is invalid. Please check your Jina auth token.');
    } else if (response.status === 404) {
        throw new Error(
            'Invalid model name ${modelName} provided. Please visit https://cloud.jina.ai/user/inference to create and use the model names listed there.'
        );
    }
    return response.json();
}

import { getBasePayload, loadPlainIntoDocument } from './helper';
import { BasePayloadInput, CaptionInput, Payload } from '../interfaces/payload';
import { DocumentArray } from '../interfaces/docarray';
import { fetch } from 'undici';

export async function caption(
    captionInput: CaptionInput,
    basePayloadInput: BasePayloadInput
): Promise<string | string[]> {
    const payload = await getCaptionPayload(captionInput, basePayloadInput);
    const result = await fetch(basePayloadInput.endpoint + '/post', {
        method: 'POST',
        headers: payload.headers,
        body: JSON.stringify(payload.body),
    });
    return await unboxCaptionResult(await result.json());
}

async function getCaptionPayload(captionInput: CaptionInput, basePayloadInput: BasePayloadInput): Promise<Payload> {
    const payload = getBasePayload(captionInput, basePayloadInput);
    payload.body.exec_endpoint = '/caption';
    const doc = await loadPlainIntoDocument(captionInput.image, 'image');
    payload.body.data = [doc] as DocumentArray;
    return payload;
}

async function unboxCaptionResult(result: any): Promise<string | string[]> {
    return result.data[0].tags.response;
}

import { Document, DocumentArray } from '../interfaces/docarray';
