import { AllParameters, BasePayloadInput, Payload } from '../interfaces/payload';
import { Document, NDArray } from '../interfaces/docarray';
import { randomUUID } from 'crypto';
import fs from 'fs';
import { fetch } from 'undici';

async function loadImageBase64(url: string): Promise<string> {
    const response = await fetch(url);
    const arrayBuffer = await response.arrayBuffer();
    const bytes = new Uint8Array(arrayBuffer);
    const base64 = btoa(String.fromCharCode(...bytes));
    return base64;
}

async function loadPlainIntoImageDocument(content: NDArray | string): Promise<Document> {
    let blob;
    try {
        if (fs.existsSync(content as string)) {
            blob = fs.readFileSync(content as string, 'base64');
        } else {
            blob = await loadImageBase64(content as string);
        }
        return { id: randomUUID(), blob: blob, uri: content as string };
    } catch (err) {
        blob = content;
        return { id: randomUUID(), blob: blob };
    }
}

export async function loadPlainIntoDocument(content: NDArray | string, mimeType?: string): Promise<Document | void> {
    if (mimeType === 'image') {
        try {
            return await loadPlainIntoImageDocument(content);
        } catch (err) {
            console.log(err);
        }
    } else if (mimeType === 'text') {
        return { id: randomUUID(), text: content as string };
    }
    if (!mimeType) {
        try {
            return await loadPlainIntoImageDocument(content as string);
        } catch (err) {
            return { id: randomUUID(), text: content as string };
        }
    }
}

export function getBasePayload(parameters: AllParameters, basePayloadInput: BasePayloadInput): Payload {
    const payloadParameters: AllParameters = {} as AllParameters;
    payloadParameters.drop_image_content = parameters.drop_image_content ?? true;

    const payload: Payload = {} as Payload;
    const headers = { 'Content-Type': 'application/json', 'Authorization': [REDACTED] };
    const body = { parameters: payloadParameters };
    payload.headers = headers;
    payload.body = body;
    return payload;
}

import { Document, DocumentArray, NDArray } from '../interfaces/docarray';
import { BasePayloadInput, Payload, RankInput } from '../interfaces/payload';
import { getBasePayload, loadPlainIntoDocument } from './helper';
import { fetch } from 'undici';

export async function rank(rankInput: RankInput, basePayloadInput: BasePayloadInput): Promise<NDArray[] | string[]> {
    const [payload, candidatesType] = await getRankPayload(rankInput, basePayloadInput);
    const result = await fetch(basePayloadInput.endpoint + '/post', {
        method: 'POST',
        headers: payload.headers,
        body: JSON.stringify(payload.body),
    });
    return await unboxRankResult(await result.json(), candidatesType);
}

async function getRankPayload(rankInput: RankInput, basePayloadInput: BasePayloadInput): Promise<[Payload, string]> {
    const payload = getBasePayload(rankInput, basePayloadInput);
    payload.body.exec_endpoint = '/rank';

    let doc: Document;
    if (rankInput.text && !rankInput.image) {
        doc = (await loadPlainIntoDocument(rankInput.text, 'text')) as Document;
    } else if (rankInput.image && !rankInput.text) {
        doc = (await loadPlainIntoDocument(rankInput.image, 'image')) as Document;
    } else if (rankInput.image && rankInput.text) {
        throw new Error('Multi-modal input not supported. Please provide only text or image input.');
    } else {
        throw new Error('Please provide either text or image to rank.');
    }

    const candidatesDocs = [] as Document[];
    let candidatesType: string;

    if (rankInput.text_candidates && !rankInput.image_candidates) {
        candidatesType = 'text';
        for (const candidate of rankInput.text_candidates) {
            candidatesDocs.push((await loadPlainIntoDocument(candidate, 'text')) as Document);
        }
    } else if (rankInput.image_candidates && !rankInput.text_candidates) {
        candidatesType = 'image';
        for (const candidate of rankInput.image_candidates) {
            candidatesDocs.push((await loadPlainIntoDocument(candidate, 'image')) as Document);
        }
    } else if (rankInput.image_candidates && rankInput.text_candidates) {
        throw new Error('Multi-modal input not supported. Please provide only text or image candidates.');
    } else {
        throw new Error('Please provide either text or image candidates to rank.');
    }

    doc.matches = candidatesDocs as Document[];
    payload.body.data = [doc] as DocumentArray;
    return [payload, candidatesType];
}

async function unboxRankResult(result: any, candidatesType: string): Promise<NDArray[] | string[]> {
    const output = [];
    for (const match of result.data[0].matches) {
        if (candidatesType === 'text') {
            output.push(match.text);
        } else {
            output.push(match.uri ?? match.blob ?? undefined);
        }
    }
    return output;
}

import { BasePayloadInput, EncodeInput, Payload } from '../interfaces/payload';
import { getBasePayload, loadPlainIntoDocument } from './helper';
import { DocumentArray, NDArray } from '../interfaces/docarray';
import { fetch } from 'undici';

export async function encode(encodeInput: EncodeInput, basePaylaodInput: BasePayloadInput): Promise<NDArray> {
    const payload = await getEncodePayload(encodeInput, basePaylaodInput);
    const result = await fetch(basePaylaodInput.endpoint + '/post', {
        method: 'POST',
        headers: payload.headers,
        body: JSON.stringify(payload.body),
    });
    return await unboxEncodeResult(await result.json());
}

async function getEncodePayload(encodeInput: EncodeInput, basePayloadInput: BasePayloadInput): Promise<Payload> {
    const payload = getBasePayload(encodeInput, basePayloadInput);
    payload.body.exec_endpoint = '/encode';

    let doc;
    if (encodeInput.text && !encodeInput.image) {
        doc = await loadPlainIntoDocument(encodeInput.text, 'text');
    } else if (encodeInput.image && !encodeInput.text) {
        doc = await loadPlainIntoDocument(encodeInput.image, 'image');
    } else if (encodeInput.image && encodeInput.text) {
        throw new Error('Multi-modal input not supported. Please provide only text or image input.');
    } else {
        throw new Error('Please provide either text or image to encode.');
    }
    payload.body.data = [doc] as DocumentArray;
    return payload;
}

async function unboxEncodeResult(result: any): Promise<NDArray> {
    return result.data[0].embedding;
}

export interface DenseNDArray {
    buffer?: string;
    shape: number[];
    dtype: string;
}
export interface SparseNDArray {
    indices?: DenseNDArray;
    values?: DenseNDArray;
    shape: number[];
}

export interface NDArray {
    dense?: DenseNDArray;
    sparse?: SparseNDArray;
    cls_name: string;
    parameters?: { [k: string]: any };
}

export interface Graph {
    adjacency?: NDArray;
    edge_features?: { [k: string]: any };
    undirected: boolean;
}

export interface NamedScore {
    value: number;
    op_name: string;
    description: string;
    operands: NamedScore[];
    ref_id: string;
}

export interface Document {
    id: string;
    granularity?: number;
    adjacency?: number;
    parent_id?: string;
    buffer?: string;
    blob?: NDArray | string;
    text?: string;
    graph?: Graph;
    chunks?: Document[];
    weight?: number;
    matches?: Document[];
    uri?: string;
    mime_type?: string;
    tags?: { [k: string]: any };
    location?: number[];
    offset?: number;
    embedding?: NDArray;
    scores?: { [k: string]: NamedScore };
    modality?: string;
    evaluations?: { [k: string]: NamedScore };
}

export type DocumentArray<T extends Document = Document> = Array<T>;

import { Document, DocumentArray, NDArray } from '../interfaces/docarray';
import { AllParameters, BasePayloadInput, Payload, UpscaleInput } from '../interfaces/payload';
import { getBasePayload, loadPlainIntoDocument } from './helper';
import { fetch } from 'undici';

export async function upscale(
    upscaleInput: UpscaleInput,
    basePaylaodInput: BasePayloadInput
): Promise<NDArray | string> {
    const payload = await getUpscalePayload(upscaleInput, basePaylaodInput);
    const result = await fetch(basePaylaodInput.endpoint + '/post', {
        method: 'POST',
        headers: payload.headers,
        body: JSON.stringify(payload.body),
    });
    return await unboxUpscaleResult(await result.json());
}

async function getUpscalePayload(upscaleInput: UpscaleInput, basePayloadInput: BasePayloadInput): Promise<Payload> {
    const payload = getBasePayload(upscaleInput as AllParameters, basePayloadInput);
    payload.body.exec_endpoint = '/upscale';

    const doc = (await loadPlainIntoDocument(upscaleInput.image, 'image')) as Document;
    const image_format = upscaleInput.image_format;
    if (image_format) {
        doc.tags = { image_format: image_format };
    }

    const output_path = upscaleInput.output_path;
    if (output_path) {
        doc.tags = { output_path: output_path };
    }
    payload.body.data = [doc] as DocumentArray;

    const scale = upscaleInput.scale;
    if (scale) {
        payload.body.parameters = { ...payload.body.parameters, scale: scale };
    }

    const quality = upscaleInput.quality;
    if (quality) {
        payload.body.parameters = { ...payload.body.parameters, quality: quality };
    }
    return payload;
}

async function unboxUpscaleResult(result: any): Promise<NDArray | string> {
    return result.data[0].blob;
}

